"""Post-run, read-only supplemental audit; no imports from Agent runtime."""

import hashlib
import json
import sqlite3
import sys
from collections import Counter
from contextlib import closing
from datetime import UTC, datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
AUDIT = ROOT / "docs/audit/superagent"


def sha(data):
    return hashlib.sha256(data).hexdigest()


def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)


def digest(value):
    return sha(canonical(value).encode("utf-8"))


def load(path):
    return json.loads(path.read_text(encoding="utf-8"))


def record(path):
    return {"path": path.relative_to(ROOT).as_posix(), "sha256": sha(path.read_bytes())}


def read_database(path):
    with closing(sqlite3.connect(path.as_uri() + "?mode=ro", uri=True, timeout=5)) as connection:
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA query_only=ON")
        connection.execute("BEGIN")
        result = {table: [dict(row) for row in connection.execute("SELECT * FROM " + table)]
                  for table in ("model_budget_attempts", "worker_runs", "worker_tool_calls",
                                "action_intents", "action_receipts", "approvals", "events",
                                "messages", "quests", "worker_capsules")}
        result["quick_check"] = connection.execute("PRAGMA quick_check").fetchone()[0]
        return result


def accounting(rows):
    return {"attempts": len(rows), "states": dict(Counter(row["state"] for row in rows)),
            "known_tokens": sum(row["input_charged"] + row["output_charged"] for row in rows
                                if row["input_charged"] is not None and row["output_charged"] is not None),
            "charged_or_reserved_tokens": sum((row["input_charged"] if row["input_charged"] is not None else row["input_reserved"])
                                              + (row["output_charged"] if row["output_charged"] is not None else row["output_reserved"])
                                              for row in rows)}


def audit(report_path):
    report = load(report_path)
    run_id = report["run_id"]
    assert report["strategy"] == "development" and report["scenario_levels"] == ["L3"]
    workspace = ROOT / ".local/superagent" / run_id
    database = workspace / "data/forge.sqlite3"
    data = read_database(database)
    events = {row["id"]: {**row, "body": json.loads(row["payload"])} for row in data["events"]}
    runs = {row["id"]: row for row in data["worker_runs"]}
    intents = {row["id"]: row for row in data["action_intents"]}
    receipts = {row["id"]: row for row in data["action_receipts"]}
    approvals = {row["id"]: row for row in data["approvals"]}
    calls = {(row["run_id"], row["call_id"]): row for row in data["worker_tool_calls"]}
    protocol_path = AUDIT / "capability-resumption-protocol.json"
    protocol = load(protocol_path)
    freeze_path = ROOT / protocol["source_freeze"]["path"]
    freeze = load(freeze_path)
    previous_path = ROOT / protocol["previous_phase"]["path"]
    previous = load(previous_path)
    changed = [item["path"] for item in freeze["files"]
               if not (ROOT / item["path"]).is_file() or sha((ROOT / item["path"]).read_bytes()) != item["sha256"]]
    historical = []
    historical_reports_unchanged = True
    historical_unknown_tools = 0
    for item in previous["preserved_reports"]:
        old_report = ROOT / item["path"]
        historical_reports_unchanged &= sha(old_report.read_bytes()) == item["sha256"]
        old = read_database(ROOT / ".local/superagent" / item["run_id"] / "data/forge.sqlite3")
        historical.extend(old["model_budget_attempts"])
        historical_unknown_tools += sum(row["state"] == "uncertain" for row in old["action_intents"])

    receipt_details = []
    verified = {}
    for row in data["worker_tool_calls"]:
        receipt = receipts.get(row["receipt_id"])
        intent = intents.get(receipt["intent_id"]) if receipt else None
        run = runs[row["run_id"]]
        bound = False
        if receipt and intent and row["result_json"]:
            result = json.loads(row["result_json"])
            bound = (intent["run_id"] == row["run_id"] and intent["call_id"] == row["call_id"]
                     and intent["tool_name"] == row["tool_name"] and intent["state"] == row["state"]
                     and all(intent[key] == run[key] for key in ("quest_id", "worker_id", "plan_id", "plan_revision", "execution_mode"))
                     and receipt["execution_mode"] == run["execution_mode"]
                     and digest(json.loads(intent["parameters_json"])) == intent["parameter_digest"]
                     and digest(json.loads(row["arguments_json"])) == intent["parameter_digest"]
                     and sha(receipt["result_json"].encode()) == receipt["result_digest"]
                     and result.get("intent_id") == intent["id"] and result.get("receipt_id") == receipt["id"]
                     and result.get("call_id") == row["call_id"] and result.get("state") == row["state"]
                     and result.get("output") == json.loads(receipt["result_json"]))
        preexecution = False
        if row["state"] == "failed" and not receipt and row["result_json"]:
            result = json.loads(row["result_json"])
            preexecution = (result.get("state") == "rejected_before_execution"
                            and result.get("call_id") == row["call_id"] and result.get("receipt_id") is None
                            and not any(item["call_id"] == row["call_id"] for item in intents.values())
                            and any(event["event_type"] == "worker.progress"
                                    and event["body"].get("run_id") == row["run_id"]
                                    and event["body"].get("failed_call_id") == row["call_id"]
                                    and event["body"].get("no_effect") is True
                                    and event["body"].get("parameter_digest") == digest(json.loads(row["arguments_json"]))
                                    for event in events.values()))
        verified[row["call_id"]] = bound
        detail = {"call_id": row["call_id"], "tool_name": row["tool_name"], "state": row["state"],
                  "receipt_id": row["receipt_id"], "source_bound_receipt": bound,
                  "proven_preexecution_rejection": preexecution}
        arguments = json.loads(row["arguments_json"])
        if "path" in arguments:
            path = Path(arguments["path"])
            target = (workspace / path).resolve()
            detail["path"] = arguments["path"]
            detail["storage_relative"] = not path.is_absolute()
            detail["inside_storage"] = target.is_relative_to(workspace)
            detail["matches_action_scope"] = bool(intent and target == Path(intent["resource_scope"]).resolve())
            if row["tool_name"] in {"file_write", "file_revise", "directory_create", "python_unittest"}:
                detail["inside_original_write_scope"] = target.is_relative_to(workspace / "work" / run["quest_id"])
        receipt_details.append(detail)

    tests = []
    candidate_bindings = []
    for quest in data["quests"]:
        directory = workspace / "work" / quest["id"]
        artifact = directory / "development.json"
        candidate = directory / "candidate.py"
        declared = load(artifact).get("test_receipt_ids", []) if artifact.is_file() else []
        candidate_hash = sha(candidate.read_bytes()) if candidate.is_file() else None
        matching = []
        for row in data["worker_tool_calls"]:
            if row["tool_name"] != "python_unittest" or runs[row["run_id"]]["quest_id"] != quest["id"]:
                continue
            receipt = receipts.get(row["receipt_id"])
            intent = intents.get(receipt["intent_id"]) if receipt else None
            approval = approvals.get(intent["approval_id"]) if intent else None
            params = json.loads(intent["parameters_json"]) if intent else {}
            output = json.loads(receipt["result_json"]) if receipt else {}
            approval_bound = bool(approval and intent["risk"] == approval["risk"] == "R2"
                                  and approval["quest_id"] == quest["id"]
                                  and approval["plan_revision"] == intent["plan_revision"]
                                  and approval["parameter_digest"] == intent["parameter_digest"]
                                  and approval["resource_scope"] == intent["resource_scope"]
                                  and approval["action_type"] == "python_unittest"
                                  and approval["status"] == "APPROVED" and approval["decided_by"] == "local_user"
                                  and approval["policy_version"] == "1" and approval["consumed_at"])
            manifest = params.get("manifest", {})
            manifest_bound = (output.get("runtime") == "cpython_unittest_v1"
                              and output.get("manifest_sha256") == digest(manifest)
                              and output.get("manifest_json") == canonical(manifest)
                              and output.get("test_module") == params.get("test_module"))
            success = (verified[row["call_id"]] and approval_bound and manifest_bound
                       and row["state"] == "succeeded" and output.get("exit_code") == 0
                       and output.get("tests_run", 0) > 0 and output.get("failures") == output.get("errors") == 0
                       and manifest.get("candidate.py") == candidate_hash)
            if success:
                matching.append(row["receipt_id"])
            tests.append({"receipt_id": row["receipt_id"], "state": row["state"],
                          "source_bound": verified[row["call_id"]], "exact_consumed_R2_approval": approval_bound,
                          "manifest_result_bound": manifest_bound, "exit_code": output.get("exit_code"),
                          "tests_run": output.get("tests_run"), "failures": output.get("failures"),
                          "errors": output.get("errors"), "candidate_sha256": manifest.get("candidate.py"),
                          "matches_final_candidate": success, "cited_by_development_report": row["receipt_id"] in declared})
        candidate_bindings.append({"quest_id": quest["id"], "candidate_sha256": candidate_hash,
                                   "artifact_sha256": sha(artifact.read_bytes()) if artifact.is_file() else None,
                                   "declared_receipt_ids": declared, "matching_success_receipt_ids": matching,
                                   "final_candidate_success_cited": bool(set(matching).intersection(declared))})

    reviews = []
    for event in events.values():
        if event["event_type"] != "review.result":
            continue
        body = event["body"]
        started = [item for item in events.values() if item["event_type"] == "review.started"
                   and all(item["body"].get(key) == body.get(key) for key in ("run_id", "call_id", "packet_sha256", "result_event_id"))]
        attempts = [row for row in data["model_budget_attempts"] if row["call_id"] == body["call_id"]]
        source = events.get(body["result_event_id"])
        bound = bool(started and source and source["event_type"] == "worker.result"
                     and source["body"].get("run_id") == body["run_id"] and attempts
                     and all(row["state"] == "settled" and row["purpose"] == "independent_reviewer" for row in attempts)
                     and body.get("execution_mode") == "live" and body.get("error_code") is None)
        reviews.append({"event_id": event["id"], "run_id": body["run_id"], "verdict": body.get("verdict"),
                        "packet_sha256": body.get("packet_sha256"), "source_and_settled_call_bound": bound})
    notices = []
    completed = {row["id"] for row in data["quests"] if row["status"] == "completed"}
    for message in data["messages"]:
        metadata = json.loads(message["metadata"])
        if message["role"] != "assistant" or metadata.get("source") != "router_notice":
            continue
        refs = metadata.get("source_event_ids", [metadata.get("event_id")])
        for reference in refs:
            event = events.get(reference)
            if event and event["quest_id"] in completed and (event["event_type"] == "quest.completed"
                    or event["event_type"] == "quest.status_changed" and event["body"].get("to") == "completed"):
                notices.append({"message_id": message["id"], "quest_id": event["quest_id"], "source_event_id": reference})

    old_accounting = accounting(historical)
    new_accounting = accounting(data["model_budget_attempts"])
    checks = {"source_freeze_matches": not changed and record(freeze_path)["sha256"] == protocol["source_freeze"]["sha256"],
              "previous_index_and_reports_unchanged": record(previous_path)["sha256"] == protocol["previous_phase"]["sha256"] and historical_reports_unchanged,
              "historical_attempts_match_131": old_accounting["attempts"] == 131,
              "historical_unknown_tool_preserved": historical_unknown_tools == 1,
              "new_attempts_within_29": new_accounting["attempts"] <= 29,
              "combined_attempts_within_160": old_accounting["attempts"] + new_accounting["attempts"] <= 160,
              "new_charged_or_reserved_within_500000": new_accounting["charged_or_reserved_tokens"] <= 500000,
              "combined_charged_or_reserved_within_2600000": old_accounting["charged_or_reserved_tokens"] + new_accounting["charged_or_reserved_tokens"] <= 2600000,
              "all_new_attempts_settled": new_accounting["states"] == {"settled": new_accounting["attempts"]},
              "failed_calls_have_receipt_or_preexecution_proof": all(row["source_bound_receipt"] or row["proven_preexecution_rejection"] for row in receipt_details if row["state"] == "failed"),
              "actual_paths_storage_relative_and_scoped": all(row["storage_relative"] and row["inside_storage"] and row["matches_action_scope"] and row.get("inside_original_write_scope", True) for row in receipt_details if "path" in row),
              "final_candidate_success_receipt_cited": bool(candidate_bindings) and all(row["final_candidate_success_cited"] for row in candidate_bindings),
              "real_source_bound_reviewer_PASS": any(row["verdict"] == "PASS" and row["source_and_settled_call_bound"] for row in reviews),
              "reviewed_completion_notice_for_all_tasks": bool(completed) and completed == {row["quest_id"] for row in notices},
              "database_quick_check": data["quick_check"] == "ok"}
    result = {"schema_version": 1, "created_at": datetime.now(UTC).isoformat(), "run_id": run_id,
              "provenance": "independent_programmatic_post_run_read_only_audit_no_new_execution",
              "auditor": {**record(Path(__file__)), "created_after_source_freeze": True,
                          "part_of_acceptance_runtime_freeze": False},
              "audit_actions": {"provider_calls": 0, "tool_replays": 0, "code_executions": 0,
                                "database_or_original_report_edits": 0, "sqlite_uri_mode": "ro"},
              "original_report": {**record(report_path), "status": report["status"], "failure_code": report.get("failure_code")},
              "source_freeze": {**record(freeze_path), "file_count": len(freeze["files"]), "changed_files": changed},
              "checks": checks, "audit_checks_all_passed": all(checks.values()),
              "historical_accounting": {**old_accounting, "unknown_tool_outcomes": historical_unknown_tools},
              "new_accounting": new_accounting, "tools": receipt_details,
              "python_test_receipts": tests, "final_candidate_and_report": candidate_bindings,
              "reviews": reviews, "final_router_notices": notices,
              "original_driver_independent_holdout": report.get("tasks", {}).get("L3", {}).get("independent_check"),
              "limitations": ["Independent code holdouts are observed from the original driver report and were not reexecuted.",
                              "A passing L3 sample does not establish multi-specialist L2 or complete joint continuity.",
                              "Receipt source integrity and approvals do not establish an OS sandbox or general task correctness."]}
    output = AUDIT / (run_id + "-resumption-independent-audit.json")
    with output.open("x", encoding="utf-8", newline="\n") as handle:
        handle.write(json.dumps(result, ensure_ascii=False, indent=2) + "\n")
    print(json.dumps({"output": str(output), "checks_all_passed": all(checks.values()),
                      "failed_checks": [name for name, passed in checks.items() if not passed],
                      "new_attempts": new_accounting["attempts"]}))


if __name__ == "__main__":
    audit(ROOT / sys.argv[1])

